let LANG = 'en';
(function detectLang(){
  let saved = null; try { saved = localStorage.getItem('shawarma-lang'); } catch(e) {}
  if (saved && S[saved]) { LANG = saved; return; }
  const prefs = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']);
  for (const l of prefs){ const c = String(l).toLowerCase().slice(0, 2); if (S[c]) { LANG = c; return; } }
  LANG = 'en';
})();
const pluralRules = {};
function T(key, vars = {}){
  let s = (S[LANG] && S[LANG][key] !== undefined) ? S[LANG][key] : (S.en[key] !== undefined ? S.en[key] : key);
  if (typeof s === 'object'){
    const n = Math.floor(Number(vars.n) || 0);
    const pr = pluralRules[LANG] || (pluralRules[LANG] = new Intl.PluralRules(LANG));
    const cat = pr.select(n);
    s = s[cat] ?? s.other ?? s.one;
  }
  return s.replace(/\{(\w+)\}/g, (m, k) => vars[k] !== undefined ? vars[k] : m);
}
const NF = () => NUMFMT[LANG] || NUMFMT.en;
const ptxt = p => (POINT_TXT[LANG] || POINT_TXT.en)[p];
function setLang(code){
  if (!S[code]) return;
  LANG = code;
  try { localStorage.setItem('shawarma-lang', code); } catch(e) {}
}
